# Simpler: enumerate all possible regions defined by adjacent separator lines
region_coords = []
if horiz_sep_rows:
    h_regions = [-1] + list(horiz_sep_rows[:-1]) + [h - 1] if horiz_sep_rows[-1] < h - 1 else [-1] + list(horiz_sep_rows)
else:
    h_regions = [-1]  # single row region spans everything

if vert_sep_cols:
    v_regions = [-1] + list(vert_sep_cols[:-1]) + [w - 1] if vert_sep_cols[-1] < w - 1 else [-1] + list(vert_sep_cols)
else:
    v_regions = [-1]

print("H-regions:", h_regions)
print("V-regions:", v_regions)

# Check each region
for i, hr in enumerate(sorted(list(set([-1]*len(horiz_sep_rows)+len([0]))) + list(range(0, h)))):
    pass

# Let me redo this more carefully
regions = []
hr_list = sorted(horiz_sep_rows)
vc_list = sorted(vert_sep_cols)

# Add -1 before first separator
hr_next = -1
hr_ranges = [(0, hr_list[i]) for i in range(len(hr_list))]
if len(hr_list) > 0 and hr_list[-1] < h - 1:
    hr_ranges.append((hr_list[-1] + 1, h))

vc_next = -1  
vc_ranges = [(0, vc_list[i]) for i in range(len(vc_list))]
if len(vc_list) > 0 and vc_list[-1] < w - 1:
    vc_ranges.append((vc_list[-1] + 1, w))

print("Row ranges:", hr_ranges)
print("Col ranges:", vc_ranges)

# Find which special colors appear in each region
region_map = {}  # (r_range, c_range) -> set of colors

for i in range(len(hr_ranges)):
    for j in range(len(vc_ranges)):
        colors_in_region = set()
        for r in range(hr_ranges[i][0], hr_ranges[i][1]):
            for c in range(vc_ranges[j][0], vc_ranges[j][1]):
                if grid[r, c] != 5:
                    colors_in_region.add(grid[r, c])
        if colors_in_region:
            region_map[(i, j)] = colors_in_region
            print(f"Region ({i},{j}) cols {vc_ranges[j]} rows {hr_ranges[i]}: {colors_in_region}")

# Now build output by filling regions with their colors
for i in range(len(hr_ranges)):
    for j in range(len(vc_ranges)):
        if (i, j) in region_map:
            for color in region_map[(i, j)]:
